#!/usr/bin/env node
/*
 * post-briefing.mjs — robust, headless-safe push of a briefing to the live app.
 *
 * WHY THIS EXISTS
 * ---------------
 * The daily briefing is generated by a scheduled Cowork/claude.ai routine
 * ("continuous-briefing-pull"): it reads Outlook email + calendar, assembles the
 * briefing JSON, then POSTs it to POST /api/briefing (KV-backed, x-api-key gated).
 *
 * The PULL and BUILD steps are reliable. The POST step has failed repeatedly
 * (6+ consecutive misses) and the live app goes stale. Root cause: the POST was
 * being attempted through a path that does not exist in a headless/cron run —
 * a browser / Chrome-extension fetch, or a sandbox whose egress differs from an
 * interactive session. A plain server-side HTTPS POST to the Vercel domain works
 * fine (verified: GET + POST both reachable, gate correctly bypassed). So the fix
 * is to ALWAYS post with a plain HTTP client like this script — never the browser.
 *
 * WHAT IT DOES
 * ------------
 *   1. Reads briefing JSON from a file arg or stdin.
 *   2. POSTs it with the x-api-key header (BRIEFING_API_KEY from env).
 *   3. Retries with backoff on network/5xx errors.
 *   4. VERIFIES by GETting the briefing back and confirming `date` round-tripped.
 *   5. Exits non-zero on any failure so the routine actually notices (the old
 *      failure mode was silent — the run "finished" but nothing landed).
 *
 * USAGE
 * -----
 *   BRIEFING_API_KEY=xxx node scripts/post-briefing.mjs briefing.json
 *   cat briefing.json | BRIEFING_API_KEY=xxx node scripts/post-briefing.mjs
 *
 * ENV
 * ---
 *   BRIEFING_API_KEY  (required)  — must match the Vercel env var exactly (case-sensitive).
 *   BRIEFING_URL      (optional)  — override target; defaults to the live app.
 *
 * EXIT CODES
 * ----------
 *   0  success (posted + verified, or posted and verify GET was inconclusive)
 *   1  POST failed after all retries / unexpected error — live app NOT updated
 *   2  bad input (no key, empty/invalid JSON, missing `date`)
 *   3  401 Unauthorized — API key mismatch (won't fix by retrying)
 *   4  POST returned 200 but the live briefing did not reflect it (wrong URL / KV lag)
 *
 * Node 18+ only (global fetch). No dependencies.
 */

const TARGET =
  process.env.BRIEFING_URL ||
  'https://daily-briefings-eight.vercel.app/api/briefing';
const API_KEY = process.env.BRIEFING_API_KEY;
const MAX_ATTEMPTS = 4;
const TIMEOUT_MS = 20000;

function log(...a) { console.error('[post-briefing]', ...a); }
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

async function readInput() {
  const fileArg = process.argv[2];
  if (fileArg) {
    const { readFile } = await import('node:fs/promises');
    return readFile(fileArg, 'utf8');
  }
  // stdin
  const chunks = [];
  for await (const c of process.stdin) chunks.push(c);
  process.stdin.pause(); // release the handle so process can exit cleanly (Node/Windows)
  return Buffer.concat(chunks).toString('utf8');
}

async function fetchWithTimeout(url, opts = {}) {
  const ctrl = new AbortController();
  const t = setTimeout(() => ctrl.abort(), TIMEOUT_MS);
  try {
    return await fetch(url, { ...opts, signal: ctrl.signal });
  } finally {
    clearTimeout(t);
  }
}

// Do the work and RETURN an exit code. Never call process.exit() mid-stream —
// on Node/Windows that trips a libuv assertion while stdin is still registered
// and corrupts the exit code the routine relies on. Set process.exitCode instead.
async function run() {
  if (!API_KEY) {
    log('FATAL: BRIEFING_API_KEY is not set. Cannot authenticate the POST.');
    return 2;
  }

  const raw = (await readInput()).trim();
  if (!raw) {
    log('FATAL: no briefing JSON provided (file arg or stdin).');
    return 2;
  }

  let briefing;
  try {
    briefing = JSON.parse(raw);
  } catch (e) {
    log('FATAL: input is not valid JSON:', e.message);
    return 2;
  }
  if (!briefing || typeof briefing !== 'object' || !briefing.date) {
    log('FATAL: briefing JSON is missing the required "date" field.');
    return 2;
  }
  log(`Posting briefing dated "${briefing.date}" (${(briefing.items || []).length} items) → ${TARGET}`);

  let posted = false;
  for (let attempt = 1; attempt <= MAX_ATTEMPTS && !posted; attempt++) {
    try {
      const res = await fetchWithTimeout(TARGET, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'x-api-key': API_KEY },
        body: JSON.stringify(briefing),
      });
      const text = await res.text();
      if (res.status === 200) {
        log(`POST ok (attempt ${attempt}): ${text}`);
        posted = true;
        break;
      }
      if (res.status === 401) {
        // Auth won't fix itself by retrying — fail fast with a clear cause.
        log(`FATAL: 401 Unauthorized — BRIEFING_API_KEY does not match the Vercel env var (exact, case-sensitive). Body: ${text}`);
        return 3;
      }
      log(`Attempt ${attempt} got HTTP ${res.status}: ${text}`);
    } catch (e) {
      // Network/DNS/timeout — this is the classic headless failure. Retry.
      log(`Attempt ${attempt} network error: ${e.name} ${e.message}`);
    }
    if (attempt < MAX_ATTEMPTS) await sleep(1000 * 2 ** (attempt - 1)); // 1s,2s,4s
  }

  if (!posted) {
    log(`FATAL: POST did not succeed after ${MAX_ATTEMPTS} attempts. Live app NOT updated.`);
    return 1;
  }

  // VERIFY — the old failures were silent; confirm the write actually landed.
  try {
    const res = await fetchWithTimeout(TARGET, { method: 'GET' });
    const got = await res.json();
    if (got && got.date === briefing.date) {
      log(`VERIFIED: live briefing now reads date "${got.date}". Done.`);
      return 0;
    }
    log(`WARNING: POST returned 200 but GET shows date "${got && got.date}" (expected "${briefing.date}"). KV may be lagging or a different deployment answered. Check the target URL.`);
    return 4;
  } catch (e) {
    log(`WARNING: POST succeeded but verification GET failed: ${e.message}. The write likely landed; confirm manually.`);
    return 0;
  }
}

run()
  .then((code) => { process.exitCode = code; })
  .catch((e) => {
    log('FATAL: unexpected error:', e && e.stack ? e.stack : e);
    process.exitCode = 1;
  });
